<?php
$pageTitle='Admin dashboard';include __DIR__.'/_top.php';$db=db();
$db->query("CREATE TABLE IF NOT EXISTS app_downloads(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,ip_address VARCHAR(45),user_agent VARCHAR(500),downloaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(downloaded_at),INDEX(user_id))");
$overview=query_one("SELECT (SELECT COUNT(*) FROM users) students,(SELECT COUNT(DISTINCT NULLIF(school_name,'')) FROM users) schools,(SELECT COUNT(*) FROM users WHERE created_at>=CURDATE()) joined_today,(SELECT COUNT(*) FROM users WHERE subscription_expires_at>NOW()) premium,(SELECT COUNT(*) FROM subscriptions WHERE status='pending') pending,(SELECT COUNT(*) FROM lessons WHERE status='active' AND content_source='textbook') lessons,(SELECT COUNT(*) FROM quiz_attempts) attempts,(SELECT COALESCE(ROUND(AVG(percentage)),0) FROM quiz_attempts) average_score,(SELECT COUNT(*) FROM app_downloads) downloads,(SELECT COUNT(*) FROM student_activity_events WHERE event_time>=NOW()-INTERVAL 24 HOUR) activity_today")??[];
$mediums=$db->query("SELECT medium,COUNT(*) total FROM users GROUP BY medium ORDER BY total DESC")->fetch_all(MYSQLI_ASSOC);
$grades=$db->query("SELECT g.grade_number,COUNT(u.id) total FROM grades g LEFT JOIN users u ON u.grade_id=g.id GROUP BY g.id ORDER BY g.grade_number")->fetch_all(MYSQLI_ASSOC);
$recent=$db->query("SELECT u.id,u.full_name,u.username,u.email,u.school_name,u.medium,u.created_at,g.grade_number,(SELECT COALESCE(SUM(points),0) FROM student_points WHERE user_id=u.id) points,(SELECT COUNT(*) FROM lesson_progress WHERE user_id=u.id AND completed_at IS NOT NULL) completed FROM users u JOIN grades g ON g.id=u.grade_id ORDER BY u.id DESC LIMIT 8")->fetch_all(MYSQLI_ASSOC);
$schools=$db->query("SELECT COALESCE(NULLIF(school_name,''),'Not provided') school,COUNT(*) students,SUM(subscription_expires_at>NOW()) premium FROM users GROUP BY school_name ORDER BY students DESC,school LIMIT 8")->fetch_all(MYSQLI_ASSOC);
$events=$db->query("SELECT e.event_type,e.detail,e.event_time,u.full_name FROM student_activity_events e JOIN users u ON u.id=e.user_id ORDER BY e.id DESC LIMIT 7")->fetch_all(MYSQLI_ASSOC);
$maxMedium=max(1,...array_map(fn($x)=>(int)$x['total'],$mediums));$maxGrade=max(1,...array_map(fn($x)=>(int)$x['total'],$grades));
?>
