<section class="admin-layout"><article class="card"><div class="dashboard-title"><h2>📊 Students by medium</h2><a href="students.php">All students →</a></div><?php foreach($mediums as $row):?><div class="chart-row"><span><?=e($row['medium'])?></span><span class="chart-track"><i style="width:<?=round(100*$row['total']/$maxMedium)?>%"></i></span><b><?=intval($row['total'])?></b></div><?php endforeach;?><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><h2>Students by grade</h2><?php foreach($grades as $row):?><div class="chart-row"><span>Grade <?=intval($row['grade_number'])?></span><span class="chart-track"><i style="width:<?=round(100*$row['total']/$maxGrade)?>%"></i></span><b><?=intval($row['total'])?></b></div><?php endforeach;?></article><article class="card"><div class="dashboard-title"><h2>⚡ Latest activity</h2><a href="chatbot_logs.php">Logs →</a></div><?php if(!$events):?><p class="muted">No student activity yet.</p><?php endif;foreach($events as $event):?><div class="activity-item"><i class="activity-dot"></i><span><b><?=e($event['full_name'])?></b><span><?=e(ucwords(str_replace('_',' ',$event['event_type'])))?> · <?=e(mb_strimwidth((string)$event['detail'],0,65,'…'))?></span><small><?=e(date('d M, g:i A',strtotime($event['event_time'])))?></small></span></div><?php endforeach;?></article></section>
<section class="card"><div class="dashboard-title"><h2>🎓 Recently registered students</h2><a class="btn alt" href="students.php">Manage all students</a></div><div class="scroll"><table class="admin-table"><tr><th>Student</th><th>School</th><th>Grade / Medium</th><th>Learning</th><th>Joined</th><th></th></tr><?php foreach($recent as $student):?><tr><td><span class="student-cell"><i class="mini-avatar"><?=e(mb_strtoupper(mb_substr($student['full_name'],0,1)))?></i><span><strong><?=e($student['full_name'])?></strong><small style="display:block;color:var(--muted)">@<?=e($student['username'])?></small></span></span></td><td><?=e($student['school_name']?:'Not provided')?></td><td>Grade <?=intval($student['grade_number'])?><br><small><?=e($student['medium'])?></small></td><td><?=intval($student['points'])?> pts · <?=intval($student['completed'])?> lessons</td><td><?=e(date('d M Y',strtotime($student['created_at'])))?></td><td><a href="student.php?id=<?=intval($student['id'])?>">View →</a></td></tr><?php endforeach;?></table></div></section>
<section class="admin-layout"><article class="card"><div class="dashboard-title"><h2>🏫 Schools</h2><span class="badge"><?=intval($overview['schools']??0)?> total</span></div><div class="school-list"><?php foreach($schools as $school):?><div class="school-row"><span><strong><?=e($school['school'])?></strong><small style="display:block;color:var(--muted)"><?=intval($school['premium'])?> premium</small></span><b><?=intval($school['students'])?> students</b></div><?php endforeach;?></div></article><article class="card download-card"><span class="badge">Application distribution</span><h2>⬇️ K Education download</h2><div class="download-count"><?=intval($overview['downloads']??0)?> downloads</div><p class="muted">Share the tracked download link or download the current application package.</p><div class="row"><a class="btn warn" href="<?=url('download.php')?>">Download package</a><button class="btn alt" type="button" id="copyDownload">Copy link</button></div></article></section>
